//! Golden-vector conformance: `dht_state` fixture generated by C++
//! libtorrent v2.1.2 (`save_dht_state` — `kademlia/dht_state.cpp`).
use bitdaemon_bencode::{Entry, bdecode, bencode};
use bitdaemon_dht::dht_state::{DhtState, read_dht_state, save_dht_state};

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("tests/data/{name}.bin")).expect("fixture")
}

/// Two nids + one v4 node, byte-exact vs upstream output.
#[test]
fn golden_dht_state_nodes() {
    let cpp = fixture("dht_state_nodes");

    let mut st = DhtState::default();
    st.nids.push((
        "1.2.3.4".parse().unwrap(),
        bitdaemon_common::Sha1Hash::from_bytes(b"01234567890123456789").unwrap(),
    ));
    st.nids.push((
        "5.6.7.8".parse().unwrap(),
        bitdaemon_common::Sha1Hash::from_bytes(b"abcdefghijklmnopqrst").unwrap(),
    ));
    st.nodes.push("9.10.11.12:6881".parse().unwrap());

    let ours = bencode(&save_dht_state(&st));
    assert_eq!(
        Entry::from(&bdecode(&ours)),
        Entry::from(&bdecode(&cpp)),
        "decoded dicts differ"
    );
    assert_eq!(ours, cpp, "bytes differ from upstream v2.1.2");

    // and reading upstream's blob back yields the same state
    let back = read_dht_state(&bdecode(&cpp));
    assert_eq!(back.nids.len(), 2);
    assert_eq!(back.nodes.len(), 1);
}
